def _page_string(laws: str) -> str:
    roots = []
    for token in laws.split("|"):
        root = token.split(".")[0].split("-")[0]
        if root not in roots:
            roots.append(root)
    return "; ".join(LAW_PAGES.get(root, "see cited Law") for root in roots)


def _fragments(level: str, rationale: str, wrong_1: str, wrong_2: str) -> list[dict[str, str]]:
    profile = EVIDENCE_PROFILE[level]
    clauses = [part.strip() for part in rationale.split(";") if part.strip()]
    if len(clauses) != profile["decisive"]:
        raise ValueError(f"{level} requires {profile['decisive']} decisive clauses, got {len(clauses)}: {rationale}")
    result = [{"role": "decisive", "text": clause} for clause in clauses]
    wrongs = (wrong_1, wrong_2)
    for index in range(profile["misleading"]):
        result.append({
            "role": "misleading",
            "text": f"An earlier non-authoritative note proposed {wrongs[index]} for this case, but it was not the controlling adjudication.",
        })
    return result


def _card(row: tuple[str, ...]) -> dict[str, Any]:
    scenario_id, level, laws, question, answer, wrong_1, wrong_2, atoms, rationale = row
    return {
        "rule_id": scenario_id,
        "scenario_id": scenario_id,
        "level": level,
        "law_reference": "Laws " + laws.replace("|", ", "),
        "source_pages": _page_string(laws),
        "source_url": RULESET["source_url"],
        "question": question,
        "answer_code": answer,
        "answer_choices": [answer, wrong_1, wrong_2],
        "required_atoms": atoms.split("|"),
        "reasoning_atom_choices": atoms.split("|") + ["TRUST_MAJORITY_NOTE", "IGNORE_SCOPE_EXCEPTION"],
        "rationale": rationale,
        "embedded_fragments": _fragments(level, rationale, wrong_1, wrong_2),
    }


RULE_CARDS = tuple(_card(row) for row in SCENARIOS)
RULE_CARDS_BY_ID = {card["rule_id"]: card for card in RULE_CARDS}
SCENARIO_SPLITS = {
    card["scenario_id"]: ("development" if index < 30 else "calibration" if index < 45 else "held_out_test")
    for index, card in enumerate(RULE_CARDS)
}

if len(RULE_CARDS) != 60 or len(RULE_CARDS_BY_ID) != 60:
    raise RuntimeError("R24 rule bank must contain 60 unique scenarios")

__all__ = ["RULE_CARDS", "RULE_CARDS_BY_ID", "SCENARIOS", "SCENARIO_SPLITS"]
